class Solution:
    def minGenerations(self, points: List[List[int]], target: List[int]) -> int:
        t = tuple(target)
        pool = [tuple(p) for p in points]
        if t in pool:
            return 0
        seen = set(pool)
        k = 0
        while True:
            k += 1
            n = len(pool)
            added = False
            for i in range(n):
                for j in range(i + 1, n):
                    c = ((pool[i][0] + pool[j][0]) // 2,
                         (pool[i][1] + pool[j][1]) // 2,
                         (pool[i][2] + pool[j][2]) // 2)
                    if c not in seen:
                        seen.add(c)
                        pool.append(c)
                        if c == t:
                            return k
                        added = True
            if not added:
                return -1

