class Solution {
public:
    int minGenerations(vector<vector<int>>& points, vector<int>& target) {
        array<int,3> t = {target[0], target[1], target[2]};
        vector<array<int,3>> pool;
        set<array<int,3>> seen;
        for (auto& p : points) {
            array<int,3> a = {p[0], p[1], p[2]};
            pool.push_back(a);
            seen.insert(a);
        }
        if (seen.count(t)) return 0;
        int k = 0;
        while (true) {
            k++;
            int n = pool.size();
            bool added = false;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    array<int,3> c = {(pool[i][0] + pool[j][0]) / 2,
                                      (pool[i][1] + pool[j][1]) / 2,
                                      (pool[i][2] + pool[j][2]) / 2};
                    if (!seen.count(c)) {
                        seen.insert(c);
                        pool.push_back(c);
                        if (c == t) return k;
                        added = true;
                    }
                }
            if (!added) return -1;
        }
    }
};

