class Solution {
    public int minGenerations(int[][] points, int[] target) {
        Set<Long> seen = new HashSet<>();
        List<long[]> pool = new ArrayList<>();
        for (int[] p : points) {
            pool.add(new long[]{p[0], p[1], p[2]});
            seen.add(key(p[0], p[1], p[2]));
        }
        long tk = key(target[0], target[1], target[2]);
        if (seen.contains(tk)) return 0;
        int k = 0;
        while (true) {
            k++;
            int n = pool.size();
            boolean added = false;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    int cx = (int)((pool.get(i)[0] + pool.get(j)[0]) / 2);
                    int cy = (int)((pool.get(i)[1] + pool.get(j)[1]) / 2);
                    int cz = (int)((pool.get(i)[2] + pool.get(j)[2]) / 2);
                    long ck = key(cx, cy, cz);
                    if (!seen.contains(ck)) {
                        seen.add(ck);
                        pool.add(new long[]{cx, cy, cz});
                        if (ck == tk) return k;
                        added = true;
                    }
                }
            if (!added) return -1;
        }
    }
    private long key(int x, int y, int z) {
        return x * 49L + y * 7L + z;
    }
}

