class Solution {
public:
    int minGenerations(vector<vector<int>>& points, vector<int>& target) {
        array<int,3> t = {target[0], target[1], target[2]};
        set<array<int,3>> seen;
        for (auto& p : points) seen.insert({p[0], p[1], p[2]});
        if (seen.count(t)) return 0;
        int k = 0;
        while (true) {
            k++;
            vector<array<int,3>> snap(seen.begin(), seen.end());
            set<array<int,3>> batch;
            int m = snap.size();
            for (int i = 0; i < m; i++)
                for (int j = i + 1; j < m; j++) {
                    array<int,3> c = {(snap[i][0] + snap[j][0]) / 2,
                                      (snap[i][1] + snap[j][1]) / 2,
                                      (snap[i][2] + snap[j][2]) / 2};
                    if (!seen.count(c)) batch.insert(c);
                }
            if (batch.empty()) return -1;
            if (batch.count(t)) return k;
            seen.insert(batch.begin(), batch.end());
        }
    }
};

