class Solution {
    public int minGenerations(int[][] points, int[] target) {
        Set<Integer> seen = new HashSet<>();
        for (int[] p : points) seen.add(key(p));
        int tk = key(target);
        if (seen.contains(tk)) return 0;
        int k = 0;
        while (true) {
            k++;
            List<int[]> snap = new ArrayList<>();
            for (int code : seen) snap.add(decode(code));
            Set<Integer> batch = new HashSet<>();
            int m = snap.size();
            for (int i = 0; i < m; i++)
                for (int j = i + 1; j < m; j++) {
                    int cx = (snap.get(i)[0] + snap.get(j)[0]) / 2;
                    int cy = (snap.get(i)[1] + snap.get(j)[1]) / 2;
                    int cz = (snap.get(i)[2] + snap.get(j)[2]) / 2;
                    int c = key(new int[]{cx, cy, cz});
                    if (!seen.contains(c)) batch.add(c);
                }
            if (batch.isEmpty()) return -1;
            if (batch.contains(tk)) return k;
            seen.addAll(batch);
        }
    }
    private int key(int[] p) { return p[0] * 49 + p[1] * 7 + p[2]; }
    private int[] decode(int c) { return new int[]{c / 49, (c % 49) / 7, c % 7}; }
}

