var minGenerations = function(points, target) {
    const key = (x, y, z) => x * 49 + y * 7 + z;
    const tk = key(...target);
    const seen = new Set(points.map(p => key(p[0], p[1], p[2])));
    if (seen.has(tk)) return 0;
    let k = 0;
    while (true) {
        k++;
        const snap = [...seen].map(code => [Math.floor(code / 49), Math.floor((code % 49) / 7), code % 7]);
        const batch = new Set();
        const m = snap.length;
        for (let i = 0; i < m; i++)
            for (let j = i + 1; j < m; j++) {
                const c = key(Math.floor((snap[i][0] + snap[j][0]) / 2),
                              Math.floor((snap[i][1] + snap[j][1]) / 2),
                              Math.floor((snap[i][2] + snap[j][2]) / 2));
                if (!seen.has(c)) batch.add(c);
            }
        if (batch.size === 0) return -1;
        if (batch.has(tk)) return k;
        for (const c of batch) seen.add(c);
    }
};
